        _q: QueryParams = {}
        put(_q, "lat", lat)
        put(_q, "lon", lon)
        put(_q, "tz", tz)
        put(_q, "date", date if date is not None else today_in(tz))
        put(_q, "time", time)
        put(_q, "ayanamsa", ayanamsa)
        put(_q, "direction", direction)
        put(_q, "lang", lang)
        put(_q, "locale", lang)
        return await self._c.request("/v1/muhurta/yatra", _q, request_options=request_options)
